using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class LoyaltyDiscountRulesAcceptanceTests
{
    private static void AssertQuote(
        int subtotal, LoyaltyTier tier, string? code, int expectedDiscount, int expectedTotal)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotal, tier, code));

        Assert.Equal(new LoyaltyDiscountQuote(subtotal, expectedDiscount, expectedTotal, tier), quote);
    }

    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_000, 18_000)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_000, 28_000)]
    [InlineData(12_000, LoyaltyTier.Gold, 1_800, 10_200)]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(subtotal, tier, null, discount, total);

    [Theory]
    [InlineData(2_999, 0, 2_999)]
    [InlineData(3_000, 450, 2_550)]
    public void S3_NoLoyaltyDiscountUnderThirtyEurosSubtotal(int subtotal, int discount, int total) =>
        AssertQuote(subtotal, LoyaltyTier.Gold, null, discount, total);

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_500, 8_500)]
    [InlineData(2_000, LoyaltyTier.Bronze, 500, 1_500)]
    public void S4_Welcome5TakesFiveEurosOffAfterLoyaltyDiscount(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_500, 17_500)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_500, 27_500)]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        AssertQuote(10_000, LoyaltyTier.Silver, code, 1_500, 8_500);

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_900, 8_100)]
    [InlineData(30_000, LoyaltyTier.Bronze, 3_000, 27_000)]
    [InlineData(2_000, LoyaltyTier.Gold, 200, 1_800)]
    public void S7_Summer10TakesTenPercentOfWhatIsLeftAtMostFifteenEuros(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(subtotal, tier, "SUMMER10", discount, total);

    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote(10_000, LoyaltyTier.Silver, "SPRING", 1_000, 9_000);

    [Theory]
    [InlineData(10_000, 2_000, 8_000)]
    [InlineData(5_000, 1_000, 4_000)]
    [InlineData(20_000, 2_000, 18_000)]
    public void S9_PlatinumMembersReceiveTwentyPercentLoyaltyDiscount(int subtotal, int discount, int total) =>
        AssertQuote(subtotal, LoyaltyTier.Platinum, null, discount, total);

    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsSubtotal(int subtotal, LoyaltyTier tier, int discount) =>
